        mock_parser.get_parallel_candidates.return_value = [mock_units[1]]

        mock_mgr = MagicMock()

        with patch("devbench.cli.BacklogParser", return_value=mock_parser):
            with patch("devbench.cli.BacklogManager", return_value=mock_mgr):
                result = cli.cmd_next()

        assert result == 0
